push.css:
.fxs .kb{--pushA:#F5C542;--pushB:#6B430A;--pushC:#FFF0B0;--rim:#F7D774;--rimD:#7A520C;--pushFace:radial-gradient(90% 90% at 36% 30%,#FFF6C4,#F8D35C 32%,#E6AA36 72%,#B57C1C)}
.fxs .push.kb{--pr:50%;box-shadow:inset 0 2px 0 rgba(255,255,255,.6),inset 0 -5px 8px rgba(140,90,10,.3),0 0 0 4px #F7D774,0 0 0 6px #7A520C,
  0 6px 0 6px #DCA436,0 7.5px 0 6px #7A520C,0 12px 0 6px #C48A22,0 13.5px 0 6px #6B4A0E,0 0 30px 12px rgba(255,214,90,.34),0 24px 34px rgba(0,0,0,.45)}
.fxs .push.kb span{font:400 44px/1 "Zen Antique Soft",serif;letter-spacing:.08em;padding-left:.08em;color:#6B430A;text-shadow:0 1.5px 0 #FFF2B0,0 -1px 0 rgba(90,55,5,.5)}
.fxs .push.kb::after{border-radius:50%;border-color:rgba(255,226,130,.95)}
.fxs .kb .kbf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:50%;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .kb .kbf svg{display:block;width:200px;height:100px}
.fxs .kb .kbd{position:absolute;left:-40px;top:-30px;width:280px;height:160px;pointer-events:none;z-index:3;font-style:normal}
.fxs .kb .kbd svg{display:block;width:280px;height:160px;overflow:visible}
.fxs .kb .kbsh{transform-box:view-box;transform-origin:0 0;animation:fxkbShine 4.6s ease-in-out infinite}
@keyframes fxkbShine{0%,55%{transform:translateX(0)}85%,100%{transform:translateX(320px)}}
.fxs .kb .kbgl{animation:fxkbGlint 3s ease-in-out infinite}
@keyframes fxkbGlint{0%,62%,100%{opacity:0;transform:scale(.3) rotate(0deg)}74%{opacity:1;transform:scale(1) rotate(30deg)}86%{opacity:0;transform:scale(.5) rotate(50deg)}}
.fxs .kb .kbtw{animation:fxkbTw 2.4s ease-in-out infinite}
@keyframes fxkbTw{0%,100%{opacity:.25;transform:scale(.5)}50%{opacity:1;transform:scale(1.1)}}
.fxs .kb .kbbo{transform-box:view-box;transform-origin:0 0;animation:fxkbBob 2.6s ease-in-out infinite alternate}
@keyframes fxkbBob{from{transform:translate(0,-3px) rotate(-5deg)}to{transform:translate(0,3px) rotate(5deg)}}
.fxs .tap.kb{font-family:"Zen Antique Soft",serif;font-weight:400;color:#FFE08A;letter-spacing:.12em;text-shadow:0 2px 0 #6B430A,0 0 10px rgba(255,200,80,.75)}
.fxs .pressed.kb{border-radius:50%;box-shadow:0 0 0 4px #F7D774,0 0 0 6px #7A520C,0 6px 0 6px #DCA436,0 7.5px 0 6px #7A520C;animation-name:fxkbPress,fxfxH}
@keyframes fxkbPress{0%{transform:scale(1)}22%{transform:scale(.92)}45%{transform:scale(1.07)}100%{transform:scale(1.5);opacity:0}}
.fxs .clips.kb{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
